"use client"

import * as React from "react"
import { EllipsisVertical } from "lucide-react"
import { cn } from "@/lib/utils"
import { Avatar, AvatarFallback, AvatarImage, type AvatarColor } from "@/components/ui/avatar"
import { IconButton } from "@/components/ui/icon-button"

/* ------------------------------------------------------------------ */
/* Shared: tiny initials avatar stack used by kanban/agenda/task rows  */
/* ------------------------------------------------------------------ */

type Person = { name: string; initials?: string; src?: string; color?: AvatarColor }

const initialsOf = (p: Person) => p.initials ?? p.name.split(" ").map((s) => s[0]).slice(0, 2).join("").toUpperCase()

function AvatarStack({ people, size = "sm", max = 3, className }: { people: Person[]; size?: "sm" | "xs" | "default"; max?: number; className?: string }) {
  const shown = people.slice(0, max)
  const rest = people.length - shown.length
  return (
    <div data-slot="avatar-stack" className={cn("flex items-center -space-x-1", className)}>
      {shown.map((p) => (
        <Avatar key={p.name} size={size} color={p.src ? undefined : (p.color ?? "indigo")} className="ring-2 ring-card" title={p.name}>
          {p.src && <AvatarImage src={p.src} alt={p.name} />}
          <AvatarFallback className="text-[10px]">{initialsOf(p)}</AvatarFallback>
        </Avatar>
      ))}
      {rest > 0 && (
        <span className="grid size-6 place-items-center rounded-full bg-muted text-[10px] font-medium text-text-secondary ring-2 ring-card">
          +{rest}
        </span>
      )}
    </div>
  )
}

/* ------------------------------------------------------------------ */
/* Event Chip + Agenda Event (calendar)                                */
/* Figma: Event Chip (722:112), Agenda Event (722:129)                 */
/* ------------------------------------------------------------------ */

type EventColor = "indigo" | "blue" | "purple" | "pink" | "red" | "orange" | "yellow" | "green"

const EVENT_BAR: Record<EventColor, string> = {
  indigo: "bg-primary",
  blue: "bg-brand-secondary",
  purple: "bg-chart-3",
  pink: "bg-brand-tertiary",
  red: "bg-destructive",
  orange: "bg-chart-2",
  yellow: "bg-brand-quaternary",
  green: "bg-success",
}

type AgendaEventProps = {
  start: React.ReactNode
  end?: React.ReactNode
  title: React.ReactNode
  meta?: React.ReactNode
  color?: EventColor
  guests?: Person[]
  onMenu?: () => void
  onClick?: () => void
  className?: string
}

function AgendaEvent({ start, end, title, meta, color = "purple", guests, onMenu, onClick, className }: AgendaEventProps) {
  return (
    // onClick: the title becomes a real button stretched over the row (keyboard and pointer),
    // the menu sits above it, so no interactive element is nested in another.
    <div
      data-slot="agenda-event"
      className={cn("relative flex items-center gap-3 border-b border-border px-5 py-3", onClick && "cursor-pointer hover:bg-muted/40 has-[[data-stretch]:focus-visible]:ring-1 has-[[data-stretch]:focus-visible]:ring-ring has-[[data-stretch]:focus-visible]:ring-inset", className)}
    >
      <div className="flex w-16 shrink-0 flex-col">
        <span className="text-xs font-medium text-foreground">{start}</span>
        {end && <span className="text-[11px] text-text-tertiary">{end}</span>}
      </div>
      <span className={cn("h-8 w-[3px] shrink-0 rounded-full", EVENT_BAR[color])} />
      <div className="flex min-w-0 flex-1 flex-col">
        {onClick ? (
          <button type="button" data-stretch onClick={onClick} className="truncate text-sm font-medium text-foreground text-left outline-none after:absolute after:inset-0 after:rounded-[inherit] after:content-['']">
            {title}
          </button>
        ) : (
          <span className="truncate text-sm font-medium text-foreground">{title}</span>
        )}
        {meta && <span className="truncate text-xs text-text-tertiary">{meta}</span>}
      </div>
      {guests && guests.length > 0 && <AvatarStack people={guests} size="sm" />}
      {onMenu && (
        <IconButton variant="ghost" size="sm" aria-label="Event menu" className="relative z-10" onClick={(e) => { e.stopPropagation(); onMenu() }}>
          <EllipsisVertical className="size-4" />
        </IconButton>
      )}
    </div>
  )
}

/* ------------------------------------------------------------------ */
/* Person Cell — avatar + name + role (+ capacity bar)                 */
/* Figma: ❖ Avatar / Person Cell (722:177)                             */
/* ------------------------------------------------------------------ */

type PersonCellProps = {
  person: Person
  role?: React.ReactNode
  /** Size=lg adds a capacity bar: value 0–100 and a label like "32h". */
  capacity?: { value: number; label?: React.ReactNode }
  className?: string
}

export { AvatarStack, AgendaEvent }
export type { Person, EventColor, AgendaEventProps, PersonCellProps }

import { Button as ButtonPrimitive } from "@base-ui/react/button"
import { cva, type VariantProps } from "class-variance-authority"
import { cn } from "cn"

const iconButtonVariants = cva(
  "group/icon-button inline-flex shrink-0 items-center justify-center border border-transparent transition duration-fast ease-entrance outline-none select-none shadow-[0px_1px_1px_0px_rgba(16,24,40,0.05)] active:translate-y-px disabled:pointer-events-none disabled:opacity-40 focus-visible:border-ring [&_svg]:pointer-events-none [&_svg]:shrink-0",
  {
    variants: {
      variant: {
        plain: "bg-card border-border-control text-foreground hover:bg-muted",
        primary: "border-primary bg-primary text-primary-foreground hover:bg-primary/90",
        brand:
          "border-brand-primary bg-brand-primary text-brand-primary-foreground hover:bg-brand-primary/90",
        gradient:
          "border-primary bg-gradient-to-b from-[#6f74f5] to-primary text-primary-foreground shadow-[inset_0px_1px_2px_0px_rgba(255,255,255,0.35)] hover:brightness-105",
        dark: "bg-inverse text-text-inverse hover:bg-(--dark-400) hover:text-white",
        light: "bg-(--light-600) text-(--light-900) hover:bg-(--light-600)/90",
        outline: "bg-card border-primary text-foreground hover:bg-primary/5",
        // Figma Type=ghost / destructive (added Sep 2026)
        ghost: "bg-transparent text-foreground shadow-none hover:bg-muted",
        destructive:
          "border-destructive bg-destructive text-destructive-foreground hover:bg-destructive/90",
      },
      shape: {
        rounded: "rounded-md",
        circle: "rounded-full",
      },
      size: {
        sm: "size-8 [&_svg]:size-4",
        md: "size-9 [&_svg]:size-[18px]",
        lg: "size-10 [&_svg]:size-5",
        xl: "size-11 [&_svg]:size-[22px]",
        "2xl": "size-12 [&_svg]:size-6",
      },
    },
    defaultVariants: {
      variant: "primary",
      shape: "rounded",
      size: "md",
    },
  }
)

function IconButton({
  className,
  variant,
  shape,
  size,
  ...props
}: ButtonPrimitive.Props & VariantProps<typeof iconButtonVariants>) {
  return (
    <ButtonPrimitive
      data-slot="icon-button"
      className={cn(iconButtonVariants({ variant, shape, size, className }))}
      {...props}
    />
  )
}

export { IconButton, iconButtonVariants }

"use client"

import * as React from "react"
import { Avatar as AvatarPrimitive } from "@base-ui/react/avatar"
import { cn } from "cn"

/** Tinted initials — mirrors the Figma Avatar "Style=<hue>_primary" variants
 *  (tint/<hue> background + tint-text/<hue> text, both mode-aware tokens). */
type AvatarColor =
  | "indigo"
  | "blue"
  | "purple"
  | "pink"
  | "red"
  | "orange"
  | "yellow"
  | "green"
  | "alternative"
  | "grey"

const AVATAR_COLOR_CLASSES: Record<AvatarColor, string> = {
  indigo: "bg-tint-indigo text-tint-text-indigo",
  blue: "bg-tint-blue text-tint-text-blue",
  purple: "bg-tint-purple text-tint-text-purple",
  pink: "bg-tint-pink text-tint-text-pink",
  red: "bg-tint-red text-tint-text-red",
  orange: "bg-tint-orange text-tint-text-orange",
  yellow: "bg-tint-yellow text-tint-text-yellow",
  green: "bg-tint-green text-tint-text-green",
  alternative: "bg-tint-alternative text-tint-text-alternative",
  grey: "bg-muted text-text-secondary",
}

function Avatar({
  className,
  size = "default",
  shape = "circle",
  variant = "plain",
  color,
  ...props
}: AvatarPrimitive.Root.Props & {
  /** Figma Avatar sizes: sm = 24px (2xs), xs = 28px, default = 36px (small), lg = 40px (medium), xl = 44px (large) */
  size?: "sm" | "xs" | "default" | "lg" | "xl"
  shape?: "circle" | "square"
  variant?: "plain" | "primary"
  /** Soft tint for initials avatars; ignored when an image renders. */
  color?: AvatarColor
}) {
  return (
    <AvatarPrimitive.Root
      data-slot="avatar"
      data-size={size}
      data-shape={shape}
      data-variant={variant}
      data-color={color}
      className={cn(
        "group/avatar relative flex size-9 shrink-0 select-none after:absolute after:inset-0 after:border after:border-border-control after:mix-blend-darken dark:after:mix-blend-lighten",
        "data-[shape=circle]:rounded-full data-[shape=circle]:after:rounded-full",
        "data-[shape=square]:rounded-md data-[shape=square]:after:rounded-md",
        "data-[size=sm]:size-6 data-[size=xs]:size-7 data-[size=lg]:size-10 data-[size=xl]:size-11",
        // Figma keeps the glyph at 16 px and only shrinks it on the two small sizes.
        "[&_svg]:size-4 data-[size=sm]:[&_svg]:size-3 data-[size=xs]:[&_svg]:size-3.5",
        "data-[variant=primary]:bg-primary data-[variant=primary]:text-primary-foreground data-[variant=primary]:after:border-transparent",
        color && AVATAR_COLOR_CLASSES[color],
        color && "after:border-transparent",
        className
      )}
      {...props}
    />
  )
}

function AvatarImage({ className, ...props }: AvatarPrimitive.Image.Props) {
  return (
    <AvatarPrimitive.Image
      data-slot="avatar-image"
      className={cn(
        "aspect-square size-full object-cover group-data-[shape=circle]/avatar:rounded-full group-data-[shape=square]/avatar:rounded-md",
        className
      )}
      {...props}
    />
  )
}

function AvatarFallback({
  className,
  ...props
}: AvatarPrimitive.Fallback.Props) {
  return (
    <AvatarPrimitive.Fallback
      data-slot="avatar-fallback"
      className={cn(
        cn(
          "flex size-full items-center justify-center bg-muted text-foreground group-data-[shape=circle]/avatar:rounded-full group-data-[shape=square]/avatar:rounded-md",
          // Initials follow the Figma type ramp: 11 / 12 / 13 / 14 / 15 px,
          // semibold everywhere except the 28 px size, which is medium.
          "text-[13px] font-semibold",
          "group-data-[size=sm]/avatar:text-[11px]",
          "group-data-[size=xs]/avatar:text-[12px] group-data-[size=xs]/avatar:font-medium",
          "group-data-[size=lg]/avatar:text-[14px] group-data-[size=xl]/avatar:text-[15px]",
          "group-data-[variant=primary]/avatar:bg-transparent group-data-[variant=primary]/avatar:text-inherit",
          "group-data-[color]/avatar:bg-transparent group-data-[color]/avatar:text-inherit"
        ),
        className
      )}
      {...props}
    />
  )
}

function AvatarBadge({ className, ...props }: React.ComponentProps<"span">) {
  return (
    <span
      data-slot="avatar-badge"
      className={cn(
        "absolute right-0 bottom-0 z-10 inline-flex items-center justify-center rounded-full bg-primary text-primary-foreground bg-blend-color ring-[1.5px] ring-(--surface) select-none",
        "group-data-[size=sm]/avatar:size-2 group-data-[size=sm]/avatar:[&>svg]:hidden",
        "group-data-[size=xs]/avatar:size-2 group-data-[size=xs]/avatar:[&>svg]:hidden",
        "group-data-[size=default]/avatar:size-2 group-data-[size=default]/avatar:[&>svg]:size-2",
        "group-data-[size=lg]/avatar:size-3 group-data-[size=lg]/avatar:[&>svg]:size-2",
        className
      )}
      {...props}
    />
  )
}

function AvatarGroup({ className, children, ...props }: React.ComponentProps<"div">) {
  const rootRef = React.useRef<HTMLDivElement>(null)

  // Distance-falloff hover lift: hovering one avatar lifts it and gently
  // lifts its neighbors, then everything snaps back with an overshoot spring
  // on mouseleave. The timing-function is set inline right before the
  // --avatar-shift/--avatar-scale writes so hover-in gets a clean ease and
  // the return gets the bouncy one, without a second class for "leaving".
  function setShifts(activeIndex: number | null, phase: "in" | "out") {
    const items = rootRef.current?.querySelectorAll<HTMLElement>("[data-avatar-hover-item]")
    if (!items) return
    const timing = phase === "out" ? "cubic-bezier(0.34, 3.85, 0.64, 1)" : "cubic-bezier(0.22, 1, 0.36, 1)"
    items.forEach((el, index) => {
      el.style.transitionTimingFunction = timing
      if (activeIndex == null) {
        el.style.setProperty("--avatar-shift", "0px")
        el.style.setProperty("--avatar-scale-active", "1")
        return
      }
      const distance = Math.abs(index - activeIndex)
      el.style.setProperty("--avatar-shift", `${(-4 * 0.45 ** distance).toFixed(3)}px`)
      el.style.setProperty("--avatar-scale-active", index === activeIndex ? "1.05" : "1")
    })
  }

  return (
    <div
      ref={rootRef}
      data-slot="avatar-group"
      onMouseLeave={() => setShifts(null, "out")}
      className={cn(
        "group/avatar-group flex -space-x-3 [&_[data-slot=avatar]]:ring-2 [&_[data-slot=avatar]]:ring-(--surface)",
        className
      )}
      {...props}
    >
      {React.Children.map(children, (child, index) => (
        <div
          data-avatar-hover-item
          onMouseEnter={() => setShifts(index, "in")}
          className="origin-center transition-transform duration-slow will-change-transform [transform:translateY(var(--avatar-shift,0px))_scale(var(--avatar-scale-active,1))] motion-reduce:[transform:none] motion-reduce:transition-none"
        >
          {child}
        </div>
      ))}
    </div>
  )
}

function AvatarGroupCount({
  className,
  ...props
}: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="avatar-group-count"
      className={cn(
        "relative flex size-9 shrink-0 items-center justify-center rounded-full bg-muted text-[12px] font-semibold text-text-secondary ring-2 ring-(--surface) group-has-data-[size=lg]/avatar-group:size-10 group-has-data-[size=xl]/avatar-group:size-11 group-has-data-[size=xs]/avatar-group:size-7 group-has-data-[size=sm]/avatar-group:size-6 [&>svg]:size-4 group-has-data-[size=lg]/avatar-group:[&>svg]:size-5 group-has-data-[size=sm]/avatar-group:[&>svg]:size-3",
        className
      )}
      {...props}
    />
  )
}

export type { AvatarColor }
export {
  Avatar,
  AvatarImage,
  AvatarFallback,
  AvatarGroup,
  AvatarGroupCount,
  AvatarBadge,
}

import type { ReactNode } from "react"
import { cn } from "@/lib/utils"

type AgendaItem = {
  id: string
  time: string
  title: string
  description?: string
  color?: string
}

function Agenda({
  items,
  className,
}: {
  items: AgendaItem[]
  className?: string
}) {
  return (
    <div className={cn("flex flex-col rounded-lg border border-border bg-card", className)}>
      {items.map((item, i) => (
        <div
          key={item.id}
          className={cn(
            "flex gap-4 p-4",
            i !== items.length - 1 && "border-b border-border"
          )}
        >
          <span className="w-14 shrink-0 text-xs font-semibold text-text-tertiary">
            {item.time}
          </span>
          <span
            className="mt-1 h-full w-0.5 shrink-0 rounded-full"
            style={{ backgroundColor: item.color ?? "var(--primary)" }}
          />
          <div className="flex flex-col gap-0.5">
            <p className="text-sm font-semibold text-foreground">{item.title}</p>
            {item.description && (
              <p className="text-[13px] text-text-secondary">{item.description}</p>
            )}
          </div>
        </div>
      ))}
    </div>
  )
}

export { Agenda }
export type { AgendaItem }
